import datetime
import time
import six
from abc import ABCMeta, abstractmethod


class Calculator(object):
    def calculate(self, cell_data_collection):
        pass

    def reset(self):
        pass


class PeakCalculator(Calculator):
    def calculate(self, throughput_data_collection):
        if throughput_data_collection.current_throughput_data.current > \
                throughput_data_collection.current_throughput_data.result.peak:
            throughput_data_collection.current_throughput_data.result.peak = \
                throughput_data_collection.current_throughput_data.current
        return throughput_data_collection.current_throughput_data.result.peak


class AverageCalculator(Calculator):
    def calculate(self, throughput_data_collection):
        new_total = (throughput_data_collection.current_throughput_data.result.average
                     * throughput_data_collection.current_throughput_data.result.count
                     + throughput_data_collection.current_throughput_data.current)
        new_count = throughput_data_collection.current_throughput_data.result.count + 1
        throughput_data_collection.current_throughput_data.result.average = new_total / new_count
        throughput_data_collection.current_throughput_data.result.count = new_count
        return throughput_data_collection.current_throughput_data.result.average


class TotalCalculator(Calculator):
    def calculate(self, throughput_data_collection):
        new_total = throughput_data_collection.current_throughput_data.result.total + \
                    throughput_data_collection.current_throughput_data.current
        new_count = throughput_data_collection.current_throughput_data.result.count + 1
        throughput_data_collection.current_throughput_data.result.count = new_count
        throughput_data_collection.current_throughput_data.result.total = new_total
        return throughput_data_collection.current_throughput_data.result.total


class MinimumCalculator(Calculator):
    def calculate(self, throughput_data_collection):
        if throughput_data_collection.current_throughput_data.current < \
                throughput_data_collection.current_throughput_data.result.minimum:
            throughput_data_collection.current_throughput_data.result.minimum = \
                throughput_data_collection.current_throughput_data.current
        return throughput_data_collection.current_throughput_data.result.minimum


class CABuffer(object):
    def __init__(self, cell_ids):
        self._cell_data_dict = {}
        for cell_id in cell_ids:
            self._cell_data_dict[cell_id] = []

    def push(self, cell_data):
        if cell_data.cell_id in self._cell_data_dict:
            self._cell_data_dict[cell_data.cell_id].append(cell_data)

    def pop(self):
        being_poped = []
        for _, cell_data_list in self._cell_data_dict.items():
            if len(cell_data_list) == 0:
                return []
            being_poped.append(cell_data_list[0])
        else:
            for _, cell_data_list in self._cell_data_dict.items():
                cell_data_list.pop(0)
            return being_poped

    def clear(self):
        for key, _ in self._cell_data_dict.items():
            self._cell_data_dict[key] = []


@six.add_metaclass(ABCMeta)
class CABufferedCalculator(Calculator):
    def __init__(self, ca_buffer):
        self._ca_buffer = ca_buffer

    @staticmethod
    def _sum(cell_data_items):
        value = 0
        for item in cell_data_items:
            value = value + item.current
        return value

    @abstractmethod
    def _calculate(self, cell_data_collection, sum_value):
        pass

    def calculate(self, throughput_data_collection):
        self._ca_buffer.push(throughput_data_collection.current_throughput_data)
        cell_data_items = self._ca_buffer.pop()
        if not cell_data_items:
            # buffer is not full
            return None
        sum_value = self._sum(cell_data_items)
        return self._calculate(throughput_data_collection, sum_value)

    def reset(self):
        self._ca_buffer.clear()


class CAPeakCalculator(CABufferedCalculator):

    def _calculate(self, cell_data_collection, sum_value):
        if sum_value > cell_data_collection.result.peak:
            cell_data_collection.result.peak = sum_value
        return cell_data_collection.result.peak


class CAMinimumCalculator(CABufferedCalculator):

    def _calculate(self, cell_data_collection, sum_value):
        if sum_value < cell_data_collection.result.minimum:
            cell_data_collection.result.minimum = sum_value
        return cell_data_collection.result.minimum


class CAAverageCalculator(CABufferedCalculator):

    def _calculate(self, cell_data_collection, sum_value):
        new_total = cell_data_collection.result.average * cell_data_collection.result.count + sum_value

        new_count = cell_data_collection.result.count + 1
        cell_data_collection.result.average = new_total / new_count
        cell_data_collection.result.count = new_count
        return cell_data_collection.result.average


class MinimumTimeIntervalCalculator(object):
    def calculate(self, throughput_data_collection, old_data):
        if not old_data or not old_data.utc_time:
            return None
        current_time_interval = (
                self._convert_utc_time_to_digital(throughput_data_collection.current_throughput_data.utc_time)
                - self._convert_utc_time_to_digital(old_data.utc_time))
        if current_time_interval < throughput_data_collection.current_throughput_data.result.min_time_interval \
                and current_time_interval > 0: # to omit the incorrect order lines
            throughput_data_collection.update_min_time_interval(throughput_data_collection.current_throughput_data,
                                                                current_time_interval)
        return throughput_data_collection.current_throughput_data.result.min_time_interval

    def _convert_utc_time_to_digital(self, utc_str):
        """
        utc_str should be like 2021-03-30T16:39:44.397005Z
        """
        UTC_FORMAT = "%Y-%m-%dT%H:%M:%S.%fZ"
        utc_obj = datetime.datetime.strptime(utc_str, UTC_FORMAT)
        timestamp = time.mktime(utc_obj.timetuple()) * 1000.0 + utc_obj.microsecond / 1000.0
        return timestamp / 1000.0
